    'مزوّد Google غير مُفعَّل في Firebase.': { en: 'Google provider is not enabled in Firebase.', fr: 'Le fournisseur Google n’est pas activé dans Firebase.', es: 'El proveedor de Google no está habilitado en Firebase.', tr: 'Google Sunucusu Firebase\'de devre dışı bırakıldı.', de: 'Google Server ist in Firebase deaktiviert.', pt: 'O servidor do Google está desativado no Firebase.', ru: 'Сервер Google отключен в Firebase.', hi: 'फ़ायरबेस में Google सर्वर अक्षम है.', zh: 'Google Server 在 Firebase 中被禁用。' },
    'هذا النطاق غير مُصرَّح به في Firebase Authentication.': { en: 'This domain is not authorized in Firebase Authentication.', fr: 'Ce domaine n’est pas autorisé dans Firebase Authentication.', es: 'Este dominio no está autorizado en Firebase Authentication.', tr: 'Bu alan adı Firebase Authentication\'da yetkili değil.', de: 'Diese Domäne ist in der Firebase-Authentifizierung nicht autorisiert.', pt: 'Este domínio não está autorizado no Firebase Authentication.', ru: 'Этот домен не авторизован в аутентификации Firebase.', hi: 'यह डोमेन फ़ायरबेस प्रमाणीकरण में अधिकृत नहीं है।', zh: '此域未在 Firebase 身份验证中获得授权。' },

