    'اسم المستخدم (4-50 حرف)': { en: 'Username (4-50 characters)', fr: 'Nom d’utilisateur (4-50 caractères)', es: 'Nombre de usuario (4-50 caracteres)', tr: 'Kullanıcı adı (4-50 karakter)', de: 'Benutzername (4-50 Zeichen)', pt: 'Nome de usuário (4 a 50 caracteres)', ru: 'Имя пользователя (4-50 символов)', hi: 'उपयोगकर्ता नाम (4-50 अक्षर)', zh: '用户名（4-50个字符）' },
    'العمر': { en: 'Age', fr: 'Âge', es: 'Edad', tr: 'yaş', de: 'das Alter', pt: 'a idade', ru: 'возраст', hi: 'को आयु', zh: '年龄' },
