    'رقم هاتف': { en: 'Phone number', fr: 'Numéro de téléphone', es: 'Número de teléfono', tr: 'Telefon numarası', de: 'Telefonnummer', pt: 'Número de telefone', ru: 'Номер телефона', hi: 'फ़ोन नंबर', zh: '电话号码' },
