        // they are English too, so the Arabic-only walker must not fight it.
        if (p && p.nodeType === 1 && p.closest && p.closest(CONTENT_SEL)) return NodeFilter.FILTER_REJECT;
        if (!AR.test(n.nodeValue)) return NodeFilter.FILTER_REJECT;
